mapper.sql:
FROM base_job_log l LEFT JOIN base_job j ON j.id = l.job_id
WHERE l.begin_time >= #{start} AND l.begin_time < #{end}
  AND (l.trigger_source IS NULL OR l.trigger_source != 3)
  AND COALESCE(l.job_type, j.job_type) = #{type}
  AND l.status = #{status}
  AND COALESCE(l.job_name, j.job_name, l.clazz_path) LIKE CONCAT('%', #{keyword}, '%') ESCAPE '!'

mapper.update:
UPDATE base_job_log SET dispatch_end_time = #{record.dispatchEndTime},
    dispatch_duration_ms = #{record.dispatchDurationMs}
WHERE id = #{record.id} AND status = 1 AND dispatch_end_time IS NULL
